import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Miscellaneous-Functions.md","filePath":"manual-en/Miscellaneous-Functions.md","lastUpdated":1785684581000}'),n={name:"manual-en/Miscellaneous-Functions.md"};function r(i,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h4 id="_7-7-9-miscellaneous-functions" tabindex="-1">7.7.9 Miscellaneous Functions <a class="header-anchor" href="#_7-7-9-miscellaneous-functions" aria-label="Permalink to &quot;7.7.9 Miscellaneous Functions&quot;">​</a></h4><p>Function: __<strong>LAG</strong> <em>( variable[, n])</em></p><p>variable must be a numeric or string variable name. <code>LAG</code> yields the value of that variable for the case n before the current one. Results in system-missing (for numeric variables) or blanks (for string variables) for the first n cases.</p><p><code>LAG</code> obtains values from the cases that become the new active dataset after a procedure executes. Thus, <code>LAG</code> will not return values from cases dropped by transformations such as <code>SELECT IF</code>, and transformations like <code>COMPUTE</code> that modify data will change the values returned by <code>LAG</code>. These are both the case whether these transformations precede or follow the use of <code>LAG</code>.</p><p>If <code>LAG</code> is used before <code>TEMPORARY</code>, then the values it returns are those in cases just before <code>TEMPORARY</code>. <code>LAG</code> may not be used after <code>TEMPORARY</code>.</p><p>If omitted, ncases defaults to 1. Otherwise, ncases must be a small positive constant integer. There is no explicit limit, but use of a large value will increase memory consumption.</p><p>Function: __<strong>YRMODA</strong> <em>( year, month, day)</em></p><p>year is a year, either between 0 and 99 or at least 1582. Unlike other PSPP date functions, years between 0 and 99 always correspond to 1900 through 1999. month is a month between 1 and 13. day is a day between 0 and 31. A day of 0 refers to the last day of the previous month, and a month of 13 refers to the first month of the next year. year must be in range. year, month, and day must all be integers.</p><p><code>YRMODA</code> results in the number of days between 15 Oct 1582 and the date specified, plus one. The date passed to <code>YRMODA</code> must be on or after 15 Oct 1582. 15 Oct 1582 has a value of 1.</p><p>Function: <em>VALUELABEL</em> <strong>( variable)</strong></p><p>Returns a string matching the label associated with the current value of variable. If the current value of variable has no associated label, then this function returns the empty string. variable may be a numeric or string variable.</p>',11)])])}const f=t(n,[["render",r]]);export{m as __pageData,f as default};
